package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Product struct {
	ID    int     `json:"id"`
	Name  string  `json:"name"`
	Price float64 `json:"price"`
	SKU   string  `json:"sku"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// sanitizeInput removes null bytes and trims whitespace
func sanitizeInput(s string) string {
	s = strings.ReplaceAll(s, "\x00", "")
	s = strings.TrimSpace(s)
	if len(s) > 100 {
		s = s[:100]
	}
	return s
}

// validateCategory checks category is alphanumeric-ish
func validateCategory(cat string) bool {
	for _, c := range cat {
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '-' || c == '_' || c == ' ' || c == '/' || c == '.' || c == ',' || c == '(' || c == ')' || c == '\'') {
			return false
		}
	}
	return true
}

func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortBy := r.URL.Query().Get("sort")
	order := r.URL.Query().Get("order")

	category = sanitizeInput(category)

	if !validateCategory(category) {
		http.Error(w, "Invalid category", 400)
		return
	}

	// Default sort handling
	if sortBy == "" {
		sortBy = "name"
	}
	if order == "" {
		order = "ASC"
	}

	// Build query - category is validated, sort/order are from controlled set... right?
	query := fmt.Sprintf(
		"SELECT id, name, price, sku FROM products WHERE category = '%s' ORDER BY %s %s LIMIT 50",
		category, sortBy, order,
	)

	log.Printf("[AUDIT] search query executed: category=%s sort=%s", category, sortBy)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.SKU); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

func getProduct(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Query().Get("id")
	var p Product
	// This one uses parameterized query correctly
	err := db.QueryRow("SELECT id, name, price, sku FROM products WHERE id = $1", id).Scan(&p.ID, &p.Name, &p.Price, &p.SKU)
	if err != nil {
		http.Error(w, "Not found", 404)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(p)
}

func main() {
	http.HandleFunc("/products/search", searchProducts)
	http.HandleFunc("/products/get", getProduct)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
